-- Runtime diagnostic queries. Bind markers are documented and must be supplied by the repository.
SELECT EXECUTION_ID, REQUIREMENT_ID, BUSINESS_KEY, STATE, RECORD_VERSION, FENCING_TOKEN, RETRY_COUNT, RESULT_CODE, TRACE_ID, CREATED_AT, UPDATED_AT
  FROM CPF_EDU_OPERATION WHERE EXECUTION_ID = :execution_id;
SELECT TARGET_ID, TARGET_KEY, STATE, ERROR_CODE, ERROR_MESSAGE, TARGET_VERSION, UPDATED_AT
  FROM CPF_EDU_OPERATION_TARGET WHERE EXECUTION_ID = :execution_id ORDER BY TARGET_KEY;
SELECT EVENT_ID, DESTINATION, EVENT_KEY, STATE, ATTEMPT_COUNT, FENCING_TOKEN, UPDATED_AT
  FROM CPF_EDU_OUTBOX WHERE EXECUTION_ID = :execution_id ORDER BY CREATED_AT;
SELECT AUDIT_ID, ACTION, BEFORE_STATE, AFTER_STATE, ACTOR_ID, REASON, TRACE_ID, CREATED_AT
  FROM CPF_EDU_OPERATION_AUDIT WHERE EXECUTION_ID = :execution_id ORDER BY CREATED_AT;

SELECT BUSINESS_KEY, BUSINESS_STATE, RECORD_VERSION, FENCING_TOKEN, PAYLOAD_JSON, CREATED_AT, UPDATED_AT
  FROM CPF_EDU_BUSINESS_RECORD
 WHERE REQUIREMENT_ID = :requirement_id AND DATA_SCOPE = :data_scope
   AND (:business_key = '*' OR BUSINESS_KEY = :business_key)
 ORDER BY UPDATED_AT DESC;

SELECT LEASE_KEY, OWNER_ID, FENCING_TOKEN, EXPIRES_AT, UPDATED_AT
  FROM CPF_EDU_LEASE WHERE LEASE_KEY = :lease_key;


-- Counterparty request/result reconciliation by idempotency key
SELECT COUNTERPARTY_REQUEST_ID, REQUIREMENT_ID, IDEMPOTENCY_KEY, REQUEST_HASH, BUSINESS_KEY,
       FAMILY_CODE, SCENARIO_CODE, STATE, RESPONSE_STATUS, RESPONSE_JSON, ATTEMPT_COUNT,
       TRACE_ID, CREATED_AT, UPDATED_AT, COMPLETED_AT
  FROM CPF_EDU_COUNTERPARTY_REQUEST
 WHERE REQUIREMENT_ID = :REQUIREMENT_ID
   AND IDEMPOTENCY_KEY = :IDEMPOTENCY_KEY;

-- Counterparty pending/unknown result operations
SELECT COUNTERPARTY_REQUEST_ID, REQUIREMENT_ID, BUSINESS_KEY, STATE, ATTEMPT_COUNT, TRACE_ID, UPDATED_AT
  FROM CPF_EDU_COUNTERPARTY_REQUEST
 WHERE STATE IN ('RECEIVED', 'PROCESSING', 'UNKNOWN_RESULT', 'RETRY_WAIT')
 ORDER BY UPDATED_AT;
